from dataclasses import dataclass
from response_builder import ResponseBuilderRecord
from version_registry import VersionRegistryRecord


VERSION_HEADER = "X-API-Version"


@dataclass
class NegotiationResult:
    ok: bool
    version: str | None
    error: str | None = None


def negotiate_version(headers: dict[str, str], registry: VersionRegistryRecord) -> NegotiationResult:
    requested = headers.get(VERSION_HEADER)
    if requested is None or not requested.strip():
        return NegotiationResult(True, registry.metadata["default"])
    requested = requested.strip()
    if requested not in registry.metadata["supported"]:
        return NegotiationResult(False, None, "unsupported_version")
    return NegotiationResult(True, requested)


def build_versioned_response(headers: dict[str, str], registry: VersionRegistryRecord, payload: dict) -> dict:
    result = negotiate_version(headers, registry)
    if not result.ok:
        return {"status": 400, "body": {"error": result.error, "supported": registry.metadata["supported"]}}
    body = dict(payload)
    body["api_version"] = result.version
    return {"status": 200, "body": body}


def default_registry() -> VersionRegistryRecord:
    return VersionRegistryRecord("api", metadata={"default": "2023-10-01", "supported": ["2023-10-01", "2024-04-01"]})

# Operational helpers used by this challenge domain.
NEGOTIATION_DOMAIN_TERMS = ('version', 'header', 'registry', 'client')

class NegotiationLedger:
    """In-memory notes for local operational decisions."""

    def __init__(self, owner="system", metadata=None):
        self.owner = owner
        self.metadata = dict(metadata or {})
        self.events = []

    def record(self, event, **details):
        item = {"event": str(event), "details": dict(details)}
        self.events.append(item)
        self.metadata[item["event"]] = self.metadata.get(item["event"], 0) + 1
        return item

    def snapshot(self):
        return {"owner": self.owner, "metadata": dict(self.metadata), "events": list(self.events)}

def negotiation_compact_metadata(metadata):
    """Return public version metadata without empty values."""
    clean = {}
    for name, value in dict(metadata or {}).items():
        if value in (None, "", [], {}):
            continue
        clean[str(name)] = value
    return clean

def negotiation_merge_context(base, extra):
    """Merge header context without mutating caller-owned dictionaries."""
    merged = negotiation_compact_metadata(base)
    for name, value in dict(extra or {}).items():
        if value is not None:
            merged[str(name)] = value
    return merged

def negotiation_labels(records, key="name"):
    """Extract labels for registry diagnostics."""
    labels = []
    for record in records or []:
        value = record.get(key) if isinstance(record, dict) else getattr(record, key, None)
        if value is not None:
            labels.append(str(value))
    return labels

def negotiation_group_by_status(records, key="status"):
    """Group client records for operator summaries."""
    grouped = {}
    for record in records or []:
        status = record.get(key, "unknown") if isinstance(record, dict) else getattr(record, key, "unknown")
        grouped.setdefault(str(status), []).append(record)
    return grouped

def negotiation_summary(records, key="status"):
    """Count negotiation records by status."""
    return {name: len(items) for name, items in negotiation_group_by_status(records, key).items()}

