from negotiation import VERSION_HEADER, build_versioned_response, default_registry, negotiate_version


def test_missing_header_uses_default_version():
    assert negotiate_version({}, default_registry()).version == "2023-10-01"


def test_exact_header_selects_requested_version():
    assert negotiate_version({VERSION_HEADER: "2024-04-01"}, default_registry()).version == "2024-04-01"


def test_lowercase_header_name_is_accepted():
    assert negotiate_version({"x-api-version": "2024-04-01"}, default_registry()).version == "2024-04-01"


def test_header_value_is_trimmed():
    assert negotiate_version({VERSION_HEADER: " 2024-04-01 "}, default_registry()).version == "2024-04-01"


def test_unsupported_explicit_version_is_error():
    result = negotiate_version({VERSION_HEADER: "2020-01-01"}, default_registry())
    assert result.ok is False and result.error == "unsupported_version"


def test_unsupported_version_response_is_400():
    assert build_versioned_response({VERSION_HEADER: "2020-01-01"}, default_registry(), {})["status"] == 400


def test_response_includes_negotiated_version():
    response = build_versioned_response({VERSION_HEADER: "2024-04-01"}, default_registry(), {"id": "o1"})
    assert response["body"]["api_version"] == "2024-04-01"


def test_default_response_includes_default_version():
    assert build_versioned_response({}, default_registry(), {})["body"]["api_version"] == "2023-10-01"


def test_common_wrong_fix_does_not_downgrade_unknown_explicit_version():
    response = build_versioned_response({VERSION_HEADER: "2099-01-01"}, default_registry(), {})
    assert response["body"]["error"] == "unsupported_version"


def test_supported_versions_are_reported_on_error():
    response = build_versioned_response({VERSION_HEADER: "2099-01-01"}, default_registry(), {})
    assert response["body"]["supported"] == ["2023-10-01", "2024-04-01"]
